package agent

import (
	"errors"

	"github.com/cookiengineer/goneat/engine/backprop"
	"github.com/cookiengineer/goneat/engine/hyperneat"
)

// NewHyperNeatBrain wraps a HyperNEAT substrate solver in a gradient-trainable
// brain. A substrate generated by a CPPN is still a normal feed-forward
// network whose connection weights live in a neat.Genome, so the returned
// brain supports both Activate (running the substrate) and Learn (backprop
// refining the substrate weights).
//
// The CPPN itself can additionally be gradient-trained with
// hyperneat.CppnTrainer.
func NewHyperNeatBrain(solver *hyperneat.Solver, trainer *backprop.Trainer, loss backprop.Loss) (*NEATBrain, error) {
	if solver == nil {
		return nil, errors.New("agent: nil hyperneat solver")
	}
	if solver.LinkCount() == 0 {
		return nil, errors.New("agent: hyperneat solver has no links")
	}
	return NewNEATBrainWithTrainer(solver.Genome(), trainer, loss)
}
